        {/* Action Bar / Footer */}
        <div className="p-6 bg-gray-50 border-t border-gray-100 shrink-0 flex items-center justify-between">

          {/* Magic Emoji Button */}
          <button
            onClick={handleAddEmojis}
            disabled={isProcessing || isRecording || !text}
            className={`p-3 rounded-full transition-all duration-200 ${
              isProcessing || isRecording || !text
                ? 'text-gray-300 cursor-not-allowed'
                : 'text-indigo-500 hover:bg-indigo-100 active:scale-95'
            }`}
            title="Add Magic Emojis"
          >
            <SparklesIcon className="w-6 h-6" />
          </button>

          {/* Microphone Button (FAB) */}
          <button
            onClick={isRecording ? handleStopRecording : handleStartRecording}
            disabled={isProcessing}
            className={`relative w-16 h-16 rounded-full flex items-center justify-center shadow-lg transition-transform duration-200 active:scale-95 focus:outline-none ${
              isProcessing ? 'bg-gray-300 cursor-not-allowed' : 
              isRecording 
                ? 'bg-red-500 text-white animate-pulse' 
                : 'bg-purple-600 text-white hover:bg-purple-700'
            }`}
          >
            {isRecording ? (
              <StopIcon className="w-8 h-8" />
            ) : (
              <MicIcon className="w-8 h-8" />
            )}

            {/* Ripple effect rings when recording */}
            {isRecording && (
              <>
                <span className="absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75 animate-ping"></span>
              </>
            )}
          </button>

          {/* Copy Button */}
          <button
            onClick={handleCopy}
            disabled={!text}
            className={`p-3 rounded-full transition-all duration-200 ${
              !text
                ? 'text-gray-300 cursor-not-allowed'
                : 'text-indigo-500 hover:bg-indigo-100 active:scale-95'
            }`}
            title="Copy Text"
          >
            <CopyIcon className="w-6 h-6" />
          </button>

        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";

// SVG Icons
