const CopyIcon = ({ className }: { className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className={className}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 17.25v3.375c0 .621-.504 1.125-1.125 1.125h-9.75a1.125 1.125 0 01-1.125-1.125V7.875c0-.621.504-1.125 1.125-1.125H6.75a9.06 9.06 0 011.5.124m7.5 10.376h3.375c.621 0 1.125-.504 1.125-1.125V11.25c0-4.46-3.243-8.161-7.5-8.876a9.06 9.06 0 00-1.5-.124H9.375c-.621 0-1.125.504-1.125 1.125v3.5m7.5 10.375H9.375a1.125 1.125 0 01-1.125-1.125v-9.25m12 6.625v-1.875a3.375 3.375 0 00-3.375-3.375h-1.5" />
  </svg>
);

// Constants
const MODE_TANGLISH = 'tanglish';
const MODE_ENGLISH = 'english';

const App = () => {
  const [mode, setMode] = useState<typeof MODE_TANGLISH | typeof MODE_ENGLISH>(MODE_TANGLISH);
  const [text, setText] = useState('');
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copySuccess, setCopySuccess] = useState(false);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Handle errors and clear them after 5 seconds
  useEffect(() => {
    if (error) {
      const timer = setTimeout(() => setError(null), 5000);
      return () => clearTimeout(timer);
    }
  }, [error]);

  const handleStartRecording = async () => {
    setError(null);
    setCopySuccess(false);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      audioChunksRef.current = [];

      mediaRecorderRef.current.ondataavailable = (event) => {
        if (event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorderRef.current.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        // Stop all tracks to release microphone
        stream.getTracks().forEach(track => track.stop());
        await processAudio(audioBlob);
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access error:", err);
      setError("Unable to access microphone. Please check permissions.");
    }
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          // Remove the Data-URL declaration (e.g. "data:audio/webm;base64,")
          const base64 = reader.result.split(',')[1];
          resolve(base64);
        } else {
          reject(new Error('Failed to convert blob to base64'));
        }
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  };

  const processAudio = async (audioBlob: Blob) => {
    setIsProcessing(true);
    setText(''); 

    try {
      const base64Audio = await blobToBase64(audioBlob);

      // Determine system instruction based on mode
      const tanglishInstruction = 'You are a transcriber. Transcribe Tamil speech into Tanglish (Tamil words in English script). Do NOT translate the meaning. Keep the tone casual (e.g., input: "Eppadi irukka?" output: "Epdi iruka...?").';
      const englishInstruction = 'Translate spoken Tamil into casual, conversational English.';

      const systemInstruction = mode === MODE_TANGLISH ? tanglishInstruction : englishInstruction;

      const response = await ai.models.generateContent({
        model: 'gemini-2.0-flash',
        contents: {
          role: 'user',
          parts: [{
            inlineData: {
              mimeType: audioBlob.type || 'audio/webm',
              data: base64Audio
            }
          }]
        },
        config: {
          systemInstruction: systemInstruction,
        }
      });

      if (response.text) {
        setText(response.text.trim());
      } else {
        setError("No text generated. Please try speaking clearly.");
      }

    } catch (err) {
      console.error("AI API Error:", err);
      setError("Failed to process audio. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAddEmojis = async () => {
    if (!text) {
      setError("Please record some text first.");
      return;
    }

    setIsProcessing(true);
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Add relevant emojis to this text without changing words or grammar: "${text}"`,
      });

      if (response.text) {
        setText(response.text.trim());
      }
    } catch (err) {
      console.error("Emoji API Error:", err);
      setError("Failed to add emojis.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCopy = async () => {
    if (!text) return;
    try {
      await navigator.clipboard.writeText(text);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      setError("Failed to copy text.");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      {/* Container */}
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden flex flex-col h-[80vh] md:h-[600px] relative">

        {/* Header */}
        <div className="bg-gradient-to-r from-purple-600 to-indigo-600 p-6 text-center shrink-0">
          <h1 className="text-3xl font-bold text-white tracking-tight">Talk Tanglish</h1>
          <p className="text-purple-100 text-sm mt-1">Speak in Tamil, get text instantly.</p>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-100 shrink-0">
          <button
            onClick={() => setMode(MODE_TANGLISH)}
            className={`flex-1 py-4 text-sm font-semibold transition-colors duration-200 ${
              mode === MODE_TANGLISH
                ? 'text-purple-600 border-b-2 border-purple-600 bg-purple-50'
                : 'text-gray-500 hover:text-gray-700 hover:bg-gray-50'
            }`}
          >
            Tanglish
          </button>
          <button
            onClick={() => setMode(MODE_ENGLISH)}
            className={`flex-1 py-4 text-sm font-semibold transition-colors duration-200 ${
              mode === MODE_ENGLISH
                ? 'text-purple-600 border-b-2 border-purple-600 bg-purple-50'
                : 'text-gray-500 hover:text-gray-700 hover:bg-gray-50'
            }`}
          >
            English Translation
          </button>
        </div>

        {/* Error Notification */}
        {error && (
          <div className="absolute top-24 left-4 right-4 z-10 bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
            <span className="block sm:inline text-sm">{error}</span>
          </div>
        )}

        {/* Main Display Area */}
        <div className="flex-1 p-6 relative flex flex-col">
          {isProcessing ? (
            <div className="flex-1 space-y-4 animate-pulse">
              <div className="h-4 bg-gray-200 rounded w-3/4"></div>
              <div className="h-4 bg-gray-200 rounded w-1/2"></div>
              <div className="h-4 bg-gray-200 rounded w-5/6"></div>
              <div className="h-4 bg-gray-200 rounded w-2/3"></div>
            </div>
          ) : (
            <textarea
              className="w-full h-full resize-none text-xl text-gray-800 placeholder-gray-300 focus:outline-none bg-transparent leading-relaxed"
              placeholder={mode === MODE_TANGLISH ? "Pesalam..." : "Speak now..."}
              value={text}
              onChange={(e) => setText(e.target.value)}
            />
          )}

          {copySuccess && (
            <div className="absolute bottom-6 right-6 bg-gray-800 text-white text-xs px-2 py-1 rounded shadow opacity-90 transition-opacity">
              Copied!
            </div>
          )}
        </div>

        {/* Action Bar / Footer */}
        <div className="p-6 bg-gray-50 border-t border-gray-100 shrink-0 flex items-center justify-between">

          {/* Magic Emoji Button */}
          <button
            onClick={handleAddEmojis}
            disabled={isProcessing || isRecording || !text}
            className={`p-3 rounded-full transition-all duration-200 ${
              isProcessing || isRecording || !text
                ? 'text-gray-300 cursor-not-allowed'
                : 'text-indigo-500 hover:bg-indigo-100 active:scale-95'
            }`}
            title="Add Magic Emojis"
          >
            <SparklesIcon className="w-6 h-6" />
          </button>

          {/* Microphone Button (FAB) */}
          <button
            onClick={isRecording ? handleStopRecording : handleStartRecording}
            disabled={isProcessing}
            className={`relative w-16 h-16 rounded-full flex items-center justify-center shadow-lg transition-transform duration-200 active:scale-95 focus:outline-none ${
              isProcessing ? 'bg-gray-300 cursor-not-allowed' : 
              isRecording 
                ? 'bg-red-500 text-white animate-pulse' 
                : 'bg-purple-600 text-white hover:bg-purple-700'
            }`}
          >
            {isRecording ? (
              <StopIcon className="w-8 h-8" />
            ) : (
              <MicIcon className="w-8 h-8" />
            )}

            {/* Ripple effect rings when recording */}
            {isRecording && (
              <>
                <span className="absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75 animate-ping"></span>
              </>
            )}
          </button>

          {/* Copy Button */}
          <button
            onClick={handleCopy}
            disabled={!text}
            className={`p-3 rounded-full transition-all duration-200 ${
              !text
                ? 'text-gray-300 cursor-not-allowed'
                : 'text-indigo-500 hover:bg-indigo-100 active:scale-95'
            }`}
            title="Copy Text"
          >
            <CopyIcon className="w-6 h-6" />
          </button>

        </div>
      </div>
    </div>
  );
};

export default App;
